// Collect every uploaded screenshot binary, validate it, and KEEP the binary intact
// so the ORIGINAL, unmodified image can be attached to Jira later (never a description,
// never an AI-generated image). Parsing the AI response must not discard this binary.
var item = $input.first();
var json = item.json || {};
var binaries = item.binary || {};
var MAX_BYTES = 10 * 1024 * 1024; // 10 MB default Jira attachment limit (see config below)

var keys = Object.keys(binaries).filter(function (k) { return /^screenshot/i.test(k); });

var files = keys.map(function (k) {
  var b = binaries[k] || {};
  var ext = b.fileExtension || (b.fileName && b.fileName.indexOf('.') !== -1 ? b.fileName.split('.').pop() : 'png');
  var fileName = b.fileName || (k + '.' + ext);
  var size = null;
  try {
    if (typeof b.data === 'string') size = Math.floor(b.data.length * 0.75);
    else if (b.data && typeof b.data.length === 'number') size = b.data.length;
  } catch (e) { size = null; }
  return { binaryProperty: k, file_name: fileName, mime_type: b.mimeType || 'application/octet-stream', size_bytes: size };
});

var images = files.filter(function (f) { return /^image\//.test(f.mime_type); });
var oversize = files.filter(function (f) { return f.size_bytes !== null && f.size_bytes > MAX_BYTES; });

var errorCode = '';
if (!files.length) errorCode = 'SCREENSHOT_MISSING';
else if (!images.length) errorCode = 'SCREENSHOT_NOT_IMAGE';
else if (oversize.length) errorCode = 'SCREENSHOT_TOO_LARGE';

var userPrompt = 'Analyse the attached bug screenshot and return ONLY a JSON object. '
  + 'Additional reporter context: ' + String(json.context || '(none)') + '. '
  + 'Environment reported: ' + String(json.environment || '(none)') + '. '
  + 'Describe exactly what is visible; do not invent logs, stack traces, dates or people.';

return [{
  json: Object.assign({}, json, {
    screenshot_files: files,
    screenshot_count: files.length,
    primary_binary_property: files.length ? files[0].binaryProperty : '',
    has_screenshot: files.length > 0,
    has_image: images.length > 0,
    oversize_files: oversize.map(function (f) { return f.file_name; }),
    screenshot_valid: !errorCode,
    error_code: errorCode,
    outcome: errorCode ? 'error' : 'proceed',
    is_retry: !!String(json.retry_issue_key || '').trim(),
    retry_issue_key: String(json.retry_issue_key || '').trim().toUpperCase(),
    max_attachment_bytes: MAX_BYTES,
    // ---- EDIT THESE THREE VALUES FOR YOUR TENANT ----
    jira_base_url: 'https://raora9487.atlassian.net',
    jira_project_key: 'KAN',
    groq_vision_model: 'qwen/qwen3.8-27b',
    // ---------------------------------------------------
    vision_system_prompt: 'You are a senior QA engineer. Given a screenshot of a software defect, write a concise Jira Bug report. Return ONLY JSON with the keys: summary (string, <= 120 chars), description (string), steps_to_reproduce (string), expected_result (string), actual_result (string), severity (one of Blocker, Critical, Major, Minor), priority (one of Highest, High, Medium, Low, Lowest), environment (string), labels (array of short strings). Base every claim on what is visible in the image; if information is missing, say so instead of inventing it.',
    vision_user_prompt: userPrompt
  }),
  binary: binaries
}];

// Parse and validate the Groq vision response into a bug draft + duplicate-search JQL.
var res = $input.first().json || {};
var ctx = $('Normalize Screenshots').first().json;
function fail(code, detail) {
  return [{ json: Object.assign({}, ctx, { outcome: 'error', error_code: code, error_details: String(detail || '').substring(0, 300), bug: null }) }];
}
if (res.error) {
  var eobj = (res.error && typeof res.error === 'object') ? res.error : {};
  var m = typeof res.error === 'string' ? res.error : (eobj.message || eobj.description || JSON.stringify(res.error));
  var auth = /401|403|invalid api key|unauthor/i.test(m);
  // Groq 429: "The service is receiving too many requests from you" / "Request too large ... reduce max_tokens"
  var rate = /429|too many requests|rate limit|request too large|reduce max_tokens|tokens per minute/i.test(m);
  if (auth) return fail('GROQ_AUTH_FAILED', m);
  if (rate) return fail('VISION_RATE_LIMITED', m);
  return fail('VISION_MODEL_FAILED', m);
}
var content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
if (content && typeof content === 'object') content = JSON.stringify(content);
if (!content) return fail('VISION_EMPTY_RESPONSE', 'Groq returned no message content');
var bug;
try {
  var s = String(content).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  bug = JSON.parse(s);
} catch (e) { return fail('VISION_INVALID_JSON', 'Vision output is not valid JSON: ' + e.message); }
if (!bug || typeof bug !== 'object' || !bug.summary) return fail('VISION_INVALID_JSON', 'Vision JSON is missing a summary');
function text(v) { return v === undefined || v === null ? '' : (typeof v === 'string' ? v.trim() : (Array.isArray(v) ? v.join(', ') : String(v))); }
var summary = text(bug.summary).substring(0, 250);
var words = summary.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(function (w) { return w.length > 3; }).slice(0, 6);
var jqlText = words.length
  ? words.map(function (k) { return 'summary ~ "' + k + '"'; }).join(' OR ')
  : 'summary ~ "' + summary.replace(/"/g, '') + '"';
var jql = 'project = "' + ctx.jira_project_key + '" AND issuetype = Bug AND (' + jqlText + ')';
return [{ json: Object.assign({}, ctx, {
  outcome: 'proceed',
  bug: {
    summary: summary,
    description: text(bug.description),
    steps_to_reproduce: text(bug.steps_to_reproduce),
    expected_result: text(bug.expected_result),
    actual_result: text(bug.actual_result),
    severity: text(bug.severity) || 'Major',
    priority: text(bug.priority) || 'Medium',
    environment: text(bug.environment) || text(ctx.environment),
    labels: Array.isArray(bug.labels) ? bug.labels : []
  },
  duplicate_jql: jql
}) }];

// Turn Jira search results into a short duplicate-candidate list for the human review gate.
var ctx = $('Validate AI Bug Report').first().json;
var items = $input.all().map(function (i) { return i.json; });
var err = items.find(function (i) { return i && i.error; });
var candidates = [];
if (!err) {
  candidates = items.filter(function (i) { return i && i.key; }).map(function (i) {
    var f = i.fields || {};
    var base = i.self ? i.self.split('/rest/api/')[0] : ctx.jira_base_url;
    return {
      key: i.key,
      summary: f.summary || i.summary || '',
      status: (f.status && f.status.name) || '',
      url: base + '/browse/' + i.key
    };
  });
}
return [{ json: Object.assign({}, ctx, {
  duplicate_candidates: candidates,
  duplicate_lookup_failed: !!err,
  duplicate_count: candidates.length
}) }];

