parameters.jsCode:
// Works for both paths: after a successful create, or when re-attaching to an existing key.
var norm = $('Normalize Screenshots').first().json;
var created = null;
try { created = $('Create Jira Bug').first().json; } catch (e) { created = null; }
var ctx = norm;
try { ctx = $('Evaluate Duplicates').first().json; } catch (e2) { ctx = norm; }
if (created && created.key) {
  var base = created.self ? created.self.split('/rest/api/')[0] : norm.jira_base_url;
  return [{ json: Object.assign({}, ctx, {
    issue_key: created.key,
    issue_id: String(created.id || ''),
    issue_url: base + '/browse/' + created.key,
    jira_base_url: base,
    is_retry: false
  }) }];
}
var rbase = norm.jira_base_url;
var key = norm.retry_issue_key;
return [{ json: Object.assign({}, norm, {
  issue_key: key,
  issue_id: '',
  issue_url: rbase + '/browse/' + key,
  jira_base_url: rbase,
  is_retry: true,
  bug: null,
  outcome: 'proceed'
}) }];

// Decide, per screenshot, whether it still needs uploading. Never duplicates an attachment.
var ctx = $('Set Issue Context').first().json;
var norm = $('Normalize Screenshots').first().json;
var resp = $input.first().json || {};

var existingNames = [];
try {
  var att = resp.fields && resp.fields.attachment;
  if (Array.isArray(att)) existingNames = att.map(function (a) { return String(a.filename || '').toLowerCase(); });
} catch (e) {}

var bin = {};
try { Object.assign(bin, $('Normalize Screenshots').first().binary || {}); } catch (e1) {}
if (!Object.keys(bin).length) { try { Object.assign(bin, $('On Form Submission').first().binary || {}); } catch (e2) {} }

var files = norm.screenshot_files || [];
var out = [];
files.forEach(function (f) {
  var b = bin[f.binaryProperty];
  var hasBinary = !!(b && b.data !== undefined && b.data !== null);
  var already = existingNames.indexOf(String(f.file_name).toLowerCase()) !== -1;
  out.push({
    json: Object.assign({}, ctx, {
      attachment_file: f.file_name,
      attachment_mime: f.mime_type,
      attachment_size: f.size_bytes,
      attachment_binary_property: f.binaryProperty,
      already_attached: already,
      has_binary: hasBinary,
      binary_missing: !hasBinary,
      needs_upload: (!already) && hasBinary
    }),
    binary: hasBinary ? { screenshot: b } : {}
  });
});
if (!out.length) {
  out.push({ json: Object.assign({}, ctx, { attachment_file: '', needs_upload: false, has_binary: false, binary_missing: true, already_attached: false }) });
}
return out;

// Reached when nothing needs uploading. Report success if already attached, or a hard
// error if the binary was lost before upload could be attempted.
var planned = $('Plan Attachments').all().map(function (i) { return i.json; });
if (planned.some(function (p) { return p.needs_upload; })) return []; // handled by the attach branch
var ctx = planned[0] || {};
var already = planned.filter(function (p) { return p.already_attached; }).map(function (p) { return p.attachment_file; });
var binaryMissing = planned.some(function (p) { return p.binary_missing; });
if (binaryMissing && !already.length) {
  return [{ json: Object.assign({}, ctx, { outcome: 'error', error_code: 'SCREENSHOT_BINARY_MISSING', error_details: 'The uploaded image binary was not available at attachment time.' }) }];
}
return [{ json: Object.assign({}, ctx, { outcome: 'success', attachment_status: 'already_attached', uploaded_attachments: [], already_attached: already }) }];

// Validate the Jira attachment API responses and aggregate the final status.
var ctx = $('Set Issue Context').first().json;
var planned = $('Plan Attachments').all().map(function (i) { return i.json; });
var toUpload = planned.filter(function (p) { return p.needs_upload; });
var results = $input.all().map(function (i) { return i.json; });

var uploaded = [];
var failed = [];
results.forEach(function (r, idx) {
  var plannedFile = toUpload[idx] || {};
  var e = r && r.error;
  if (e && !Array.isArray(r)) {
    var m = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
    var code = /413|too large|entity too large/i.test(m) ? 'ATTACHMENT_TOO_LARGE'
      : (/403|forbidden|permission/i.test(m) ? 'ATTACHMENT_PERMISSION_DENIED' : 'ATTACHMENT_UPLOAD_FAILED');
    failed.push({ file: plannedFile.attachment_file || '', code: code, error: String(m).substring(0, 200) });
    return;
  }
  var arr = Array.isArray(r) ? r : [r];
  arr.forEach(function (a) {
    if (a && a.filename) uploaded.push({ file: a.filename, id: a.id, size: a.size, url: a.content });
  });
});

var already = planned.filter(function (p) { return p.already_attached; }).map(function (p) { return p.attachment_file; });
var binaryMissing = planned.some(function (p) { return p.binary_missing; });
var outcome = failed.length ? 'partial' : 'success';
var code = failed.length ? failed[0].code : '';
if (binaryMissing && !uploaded.length && !already.length) { outcome = 'error'; code = 'SCREENSHOT_BINARY_MISSING'; }

return [{ json: Object.assign({}, ctx, {
  outcome: outcome,
  error_code: code,
  attachment_status: outcome === 'success' ? 'uploaded' : (uploaded.length ? 'partial' : 'failed'),
  uploaded_attachments: uploaded,
  failed_attachments: failed,
  already_attached: already,
  binary_missing: binaryMissing
}) }];

var ctx = $('Evaluate Duplicates').first().json;
var decision = ($('Human Approval').first().json || {}).decision || 'Reject';
return [{ json: Object.assign({}, ctx, { outcome: 'rejected', decision: decision }) }];

// Compose the final result for every outcome. Never report full success unless both the
// Jira issue AND the original screenshot attachment are confirmed.
var j = $input.first().json || {};
function context() {
  try { return $('Evaluate Duplicates').first().json; } catch (e1) {}
  try { return $('Normalize Screenshots').first().json; } catch (e2) {}
  return {};
}
var c = context();
var key = j.issue_key || c.issue_key || '';
var url = j.issue_url || c.issue_url || '';
var bug = j.bug || c.bug || {};
var summary = bug.summary || '';
var outcome = j.outcome || 'error';
var errorCode = j.error_code || c.error_code || '';
var lines = [];

if (outcome === 'success') {
  var names = (j.uploaded_attachments || []).map(function (a) { return a.file || a.filename; });
  names = names.concat(j.already_attached || []);
  lines.push('Jira Bug Created Successfully');
  lines.push('');
  lines.push('Issue: ' + key);
  lines.push('Summary: ' + summary);
  lines.push('Priority: ' + (bug.priority || ''));
  lines.push('Screenshot: ' + (names.join(', ') || 'n/a'));
  lines.push('Attachment Status: ' + (names.length ? 'Successfully uploaded' : 'No screenshots attached'));
  lines.push('Jira URL: ' + url);
} else if (outcome === 'partial') {
  lines.push('PARTIAL SUCCESS - Jira bug created, screenshot attachment FAILED');
  lines.push('');
  lines.push('Issue: ' + key);
  lines.push('Summary: ' + summary);
  lines.push('Jira URL: ' + url);
  lines.push('Attachment Status: FAILED (' + (errorCode || 'ATTACHMENT_UPLOAD_FAILED') + ')');
  if ((j.failed_attachments || []).length) lines.push('Failed files: ' + j.failed_attachments.map(function (f) { return f.file; }).join(', '));
  lines.push('');
  lines.push('The Jira bug EXISTS but the screenshot was not attached. Do NOT create another bug.');
  lines.push('Safe retry: resubmit the same screenshot using the "Re-attach only to existing Jira key" field with key ' + key + '.');
} else if (outcome === 'rejected') {
  lines.push('Report rejected by the reviewer. No Jira issue was created and nothing was attached.');
} else if (errorCode === 'VISION_RATE_LIMITED') {
  lines.push('The Groq vision request could not be completed.');
  lines.push('Reason: the Groq service is rate-limited (too many requests / output-token limit). This is temporary.');
  lines.push('Action: wait about a minute, then submit the screenshot again.');
  lines.push('(No Jira issue was created.)');
  if (j.error_details) lines.push('Details: ' + j.error_details);
} else {
  lines.push('Bug report could not be completed.');
  lines.push('Error: ' + (errorCode || 'UNKNOWN_ERROR'));
  if (j.error_details) lines.push('Details: ' + j.error_details);
  if (key) lines.push('Jira issue: ' + key + ' ' + url);
}
return [{ json: { output: lines.join('\n'), outcome: outcome, issue_key: key, issue_url: url, attachment_status: j.attachment_status || '' } }];
